const body = $input.first().json.body;
const match = (body.comment.body || '').trim().match(/^\/build\s+(ios|android)\b/i);
const target = match ? match[1].toLowerCase() : 'ios';
return [{ json: {
  target,
  prNumber: body.issue.number,
  repoOwner: body.repository.owner.login,
  repoName: body.repository.name,
  repoFull: body.repository.full_name
}}];

const stdout = $input.first().json.stdout || '';
const stderr = $input.first().json.stderr || '';
const target = $('Parse command').item.json.target;
const shortSha = (($('Get PR head SHA').item.json.head || {}).sha || '').slice(0, 7);

const landingMatch = stdout.match(/landing: (\S+)/);
const downloadMatch = stdout.match(/download: (\S+)/);

// stderr carries the real build output for both targets (gradle + xcodebuild
// are redirected with >&2). stdout only has trailing marker lines. Prefer
// stderr so the comment's log tail is informative; fall back to stdout if
// stderr happens to be empty.
const logSource = (stderr && stderr.trim()) ? stderr : stdout;

const downloadLabel = target === 'ios' ? 'Download IPA' : 'Download APK (GitHub)';
const installLabel = target === 'ios' ? 'Install page on onym.chat (open in Safari on iOS)' : 'Install page on onym.chat';

const lines = [];
lines.push(`**${target}** build finished for \`${shortSha}\``);
lines.push('');
if (landingMatch) lines.push(`🔗 [${installLabel}](${landingMatch[1]})  `);
if (downloadMatch) lines.push(`📦 [${downloadLabel}](${downloadMatch[1]})`);
lines.push('');
lines.push('<details><summary>build log (tail)</summary>');
lines.push('');
lines.push('```');
lines.push(logSource.slice(-1500));
lines.push('```');
lines.push('');
lines.push('</details>');

return [{ json: { body: lines.join('\n') } }];
